html:
{% set result = frappe.call('healthnet_cashflow.api.trial_balance_sheet_data.get_trial_balance_sheet_prepared_data') %}

{% if not result.success %}
    <div style="padding: 20px; text-align: center; color: red;">
        <h3>{{ result.message }}</h3>
    </div>
{% else %}

{% set filters = result.applied_filters %}
{% set columns = result.columns %}
{% set data = result.data %}
{% set company = filters.company or '' %}


<style>
	.financial-statements-important td {
		font-weight: bold;
	}
	.financial-statements-blank-row td {
		height: 37px;
	}
	.table-bordered td, .table-bordered th {
		border: 1px solid #dee2e6;
	}
</style>


<table style="margin-top:-10px; table-layout:fixed; width:100%;">
    <tr>
        <td colspan="18" style="text-align:center; font-weight:bold; font-size:16px;">
            TRIAL BALANCE
        </td>
    </tr>

    <!-- Company Name -->
    <tr>
        <td colspan="18" style="text-align:center; font-size:12px; font-weight:600;">
            {{ filters.company }}
        </td>
    </tr>

    <tr>
        <td colspan="18" style="text-align:center; font-size:11px;">
            Currency: {{ filters.presentation_currency or 'GHS' }}
        </td>
    </tr>

    <!-- Print Date & Time -->
    <tr>
    <td colspan="18" style="text-align:center; font-size:10px;">
        Printed On: {{ frappe.utils.now_datetime().strftime("%d/%m/%Y %H:%M:%S") }}
    </td>
</tr>

</table>

<table style="table-layout:fixed; width:100%; margin-top:10px; border-top:1px solid black; font-size:11px;">
    <tr style="border-bottom:1px solid black;">
        <td colspan="6" style=" padding:5px;">
            <b>Particulars</b>
        </td>
        {% for col in columns[1:] %}
            <td colspan="3" style="text-align:right; padding:5px;">
                <b>{{ col.label }}</b>
            </td>
        {% endfor %}
    </tr>

    {% for row in data %}
        {% set row_class = "" if (row.parent_account or row.parent_section) else "financial-statements-important" %}
        {% set row_class = row_class + ("" if (row.account_name or row.section) else " financial-statements-blank-row") %}

        <tr class="{{ row_class }}" style="{% if loop.index is odd %}background-color: #f9f9f9;{% endif %}">
            <td colspan="6" style="padding:4px;">
                {% if row.account %}
                    {% set is_group = frappe.db.get_value(
                        "Account",
                        row.account,
                        "is_group"
                    ) %}

                    {% if is_group == 1  %}
                        <span style="font-weight: 600;">
                            {{ row.account_name }}
                        </span>
                    {% else %}
                        <span>
                            {{ row.account_name }}
                        </span>
                    {% endif %}
                {% else %}
                    {{ row.section or '' }}
                {% endif %}

            </td>

            {% for col in columns[1:] %}
                <td colspan="3" style="text-align:right; padding:4px;">
                    {% set value = row.get(col.fieldname) %}
                    {% set currency = filters.presentation_currency or 'GHS' %}
                    {% if value is not none and value != "" and value != 0 %}
                    <span style="{% if is_group == 1 %}font-weight:600;{% endif %}">
                        {% if value | float < 0 %}
                            ({{ "{:,.2f}".format((value | float) | abs) }})
                        {% else %}
                            {{ "{:,.2f}".format(value | float) }}
                        {% endif %}
                    {% endif %}
                    </span>
                </td>
            {% endfor %}
        </tr>
    {% endfor %}
</table>


{% endif %}
